class Solution {
  generateParenthesis(n) {
    return this.generateValidPermutations("", [], 0, 0, n);
  }

  generateValidPermutations(ps, result, open, closed, n) {
    if (open > n || closed > n || closed > open) {
      return;
    }
    if (open === n && closed === n) {
      result.push(ps);
      return;
    }

    this.generateValidPermutations(ps + "(", result, open + 1, closed, n);
    this.generateValidPermutations(ps + ")", result, open, closed + 1, n);

    return result;
  }
}

